#!/usr/bin/env python3
"""Generate the 16x16 pixel font atlas (RGBA PNG) for Phase 35 (+ PRE-1).

Deterministic: the glyph tables are static data in this file, so the
output is stable across runs and platforms. Re-run after editing this
file to refresh assets/textures/font.png.

Atlas layout (256x512, 32px cells; 16 rows):
  - rows 4..15 are indexed by ASCII code: cell (c % 8, c // 8), so ASCII
    codes 32..126 keep the original c // 8 row indexing (cell 127 = DEL
    is dead, and since CRAFT-4 holds the 33rd CJK glyph, 作);
  - rows 0..3 hold the PRE-1 CJK set: ASCII codes 0..31 are control
    characters that never render (src/ui/font.cpp maps them to '?'), so
    those 32 cells were dead transparent space. Reusing the dead cells
    keeps the atlas 256x512 and the ASCII glyph UVs bit-identical
    (PRE-1 red line) instead of growing the texture height;
  - CRAFT-4: the CJK set grew to 33 (PRE-1 omitted 作, the
    crafting-table title rendered 工?台). The 33rd glyph takes the dead
    ASCII-DEL cell 127 (col 7, row 15) via the explicit CJK_CELL map —
    the original 32 keep their cells 0..31, so every PRE-1 UV and all
    of rows 0..14 stay bit-identical;
  - each 16x16 glyph is drawn centered in its 32px cell (8px offset);
  - ink pixels are white with full alpha; everything else is transparent.

ASCII glyph data: the FONT table was extracted once (offline) from
DejaVu Sans Bold, em 16px, baseline at cell row 12 (descenders use rows
13..15), coverage threshold 128. 2 px strokes, monospace (the advance
is the full 16 px cell, see src/ui/font.cpp).

CJK glyph data: the CJK_FONT table was extracted once (offline) from
Noto Sans CJK SC Regular (the 'SC' face of NotoSansCJK-Regular.ttc),
em 16px: the rasterizer's line box (ascent 19 px, descent 5 px) is
windowed to its rows 5..20 (the placement that minimizes clipped ink
for this set: only the faintest anti-aliased row of '；' is lost) and
centered on the 16 px advance, coverage threshold >= 128. CJK glyphs
use the same 16 px monospace advance as ASCII (PRE-1: mixed text keeps
one advance per codepoint). The TTF is a TOOL-TIME input only — the
game build never needs it, same as the ASCII table.

The game (src/ui/font.cpp) maps a decoded UTF-8 codepoint to its cell
and reads the 16x16 sub-rect; unknown codepoints fall back to the '?'
glyph.
"""
import os
import struct
import zlib

W, H = 256, 512
CELL = 32
OUT = os.path.join(os.path.dirname(__file__), "..", "assets",
                   "textures", "font.png")


def chunk(tag: bytes, data: bytes) -> bytes:
    c = struct.pack(">I", len(data)) + tag + data
    c += struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
    return c


def write_png(path: str, pixels) -> None:
    """pixels: list of rows, each a list of (r, g, b, a) tuples."""
    sig = b"\x89PNG\r\n\x1a\n"
    ihdr = struct.pack(">IIBBBBB", W, H, 8, 6, 0, 0, 0)
    raw = bytearray()
    for row in pixels:
        raw.append(0)  # filter: None
        for (r, g, b, a) in row:
            raw += bytes((r, g, b, a))
    out = (sig + chunk(b"IHDR", ihdr)
           + chunk(b"IDAT", zlib.compress(bytes(raw)))
           + chunk(b"IEND", b""))
    with open(path, "wb") as f:
        f.write(out)


